diff --git a/src/store.js b/src/store.js
index f3ed7b4..fd3dd89 100644
--- a/src/store.js
+++ b/src/store.js
@@ -6,6 +6,9 @@ const shelf = [
   { id: 4, name: "yogurt", qty: 4, unit: "cup", tags: ["fridge"], expires: "2026-10-20" },
 ];

+// Highest id ever stored. Ids are never reused, even after removal.
+let highestId = Math.max(0, ...shelf.map((item) => item.id));
+
 /** Every item on the shelf (copies). */
 export async function fetchItems() {
   return shelf.map((item) => ({ ...item, tags: [...item.tags] }));
@@ -16,5 +19,19 @@ export async function saveItem(item) {
   const i = shelf.findIndex((s) => s.id === item.id);
   if (i < 0) shelf.push(item);
   else shelf[i] = item;
+  highestId = Math.max(highestId, item.id);
   return item;
 }
+
+/** The next id never used by any item, including removed ones. */
+export async function nextId() {
+  return highestId + 1;
+}
+
+/** Removes the item with `id`; true if it was on the shelf. */
+export async function deleteItem(id) {
+  const i = shelf.findIndex((s) => s.id === id);
+  if (i < 0) return false;
+  shelf.splice(i, 1);
+  return true;
+}
